tasks = dict(zip(values('Tasks', 'K420:K425'), values('Tasks', 'L420:L425')))
deps = list(zip(values('Dependencies', 'K38:K43'), values('Dependencies', 'L38:L43')))
succs = {t: [] for t in tasks}
preds = {t: [] for t in tasks}
for s, p in deps:
    succs[p].append(s)
    preds[s].append(p)

# Calculate earliest start (ES) and earliest finish (EF)
es = {t: 0 for t in tasks}
ef = {t: 0 for t in tasks}

# Topological sort order (simple iterative approach for DAG)
in_degree = {t: len(preds[t]) for t in tasks}
queue = [t for t in tasks if in_degree[t] == 0]
order = []
while queue:
    u = queue.pop(0)
    order.append(u)
    for v in succs[u]:
        in_degree[v] -= 1
        if in_degree[v] == 0:
            queue.append(v)

for t in order:
    es[t] = max([ef[p] for p in preds[t]] + [0])
    ef[t] = es[t] + tasks[t]

project_duration = max(ef.values())

# Calculate latest finish (LF) and latest start (LS)
ls = {t: 0 for t in tasks}
lf = {t: 0 for t in tasks}
for t in tasks:
    lf[t] = project_duration

for t in reversed(order):
    if succs[t]:
        lf[t] = min([ls[s] for s in succs[t]])
    else:
        lf[t] = project_duration
    ls[t] = lf[t] - tasks[t]

total_slack = ls['Permit'] - es['Permit']
result = int(total_slack)

